export default function Skills() {
  return (
    <>
      <div className="closing-tag">
        <svg
          id="tag"
          xmlns="http://www.w3.org/2000/svg"
          height="24px"
          viewBox="0 -960 960 960"
          width="24px"
        >
          <defs>
            <linearGradient id="tagGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#4F8CFF" />
              <stop offset="40%" stopColor="#5B7CFF" />
              <stop offset="70%" stopColor="#6A5CFF" />
              <stop offset="100%" stopColor="#8B5CF6" />
            </linearGradient>
          </defs>
          <path
            fill="url(#tagGradient)"
            d="M240-280 40-480l200-200 56 56-143 144 143 144-56 56Zm178 132-76-24 200-640 76 24-200 640Zm302-132-56-56 143-144-143-144 56-56 200 200-200 200Z"
          />
        </svg>

        <h3> Skills</h3>
      </div>

      <section className="skills-section" id="skills">
        <div className="marquee-container">
          <div className="marquee-track">
            {[...techIcons, ...techIcons].map((icon, index) => (
              <div key={index} className="marquee-item">
                {icon.svg}
                <span className="marquee-label">{icon.name}</span>
              </div>
            ))}
          </div>
        </div>
      </section>
    </>
  );
}
